/** Tabs that stay out of the sitemap: personal device data or duplicate views. */
export const NON_INDEXABLE_TABS: NavigationTab[] = ['bookmarks', 'mistakes', 'past-papers-pdf'];

/** Path of a navigation tab, e.g. 'mcqs' -> '/mcqs'. */
export function pathForTab(tab: NavigationTab): string {
  return TAB_PATHS[tab];
}

/** Absolute public URL of a section on the canonical origin. */
export function absoluteUrlForPath(path: string): string {
  return `${SITE_ORIGIN}${path}`;
}

/** Current browser pathname, or '/' when no browser location is available (e.g. server rendering). */
export function currentPathname(): string {
  if (typeof window === 'undefined') return '/';
  return window.location?.pathname ?? '/';
}

/**
 * Resolve a browser pathname to a navigation tab. Trailing slashes and letter
 * case are ignored. Unknown paths fall back to the home tab.
 */
export function tabFromPathname(pathname: string): NavigationTab {
  let normalized = (pathname || '/').toLowerCase();
  if (normalized.length > 1) normalized = normalized.replace(/\/+$/, '');
  if (normalized === '') normalized = '/';
  const match = (Object.keys(TAB_PATHS) as NavigationTab[]).find((tab) => TAB_PATHS[tab] === normalized);
  return match ?? 'home';
}

/**
 * Apply per-section document metadata (title, description, canonical and
 * Open Graph URL). Search engines that render JavaScript read these values,
 * so each section is indexed under its own URL rather than the homepage.
 */
export function applySectionMetadata(tab: NavigationTab): void {
  if (typeof document === 'undefined') return;
  const section = SITE_SECTIONS.find((item) => item.tab === tab) ?? SITE_SECTIONS[0];
  const url = absoluteUrlForPath(section.path);

  document.title = section.title;
  setMetaContent('meta[name="description"]', 'name', 'description', section.description);
  setMetaContent('meta[property="og:title"]', 'property', 'og:title', section.title);
  setMetaContent('meta[property="og:description"]', 'property', 'og:description', section.description);
  setMetaContent('meta[property="og:url"]', 'property', 'og:url', url);

  let canonical = document.querySelector<HTMLLinkElement>('link[rel="canonical"]');
  if (!canonical) {
    canonical = document.createElement('link');
    canonical.rel = 'canonical';
    document.head.appendChild(canonical);
  }
  canonical.href = url;
}

function setMetaContent(selector: string, attr: 'name' | 'property', key: string, content: string): void {
  let element = document.querySelector<HTMLMetaElement>(selector);
  if (!element) {
    element = document.createElement('meta');
    element.setAttribute(attr, key);
    document.head.appendChild(element);
  }
  element.content = content;
}
